/**
 * Placeholder base64 images for mock AI responses
 * These are 300x169 (16:9) placeholder images with different themes
 * Using proper-sized placeholder images that are visible
 */

// Scene 1: Establishing shot - Blue gradient placeholder
export const PLACEHOLDER_ESTABLISHING =
  "data:image/svg+xml;base64,";

// Scene 2: Close-up - Green gradient placeholder
export const PLACEHOLDER_CLOSEUP =
  "data:image/svg+xml;base64,";

// Scene 3: Action sequence - Orange gradient placeholder
export const PLACEHOLDER_ACTION =
  "data:image/svg+xml;base64,";

// Scene 4: Resolution - Purple gradient placeholder
export const PLACEHOLDER_RESOLUTION =
  "data:image/svg+xml;base64,";

// Array of all placeholder images
export const PLACEHOLDER_IMAGES = [
  PLACEHOLDER_ESTABLISHING,
  PLACEHOLDER_CLOSEUP,
  PLACEHOLDER_ACTION,
  PLACEHOLDER_RESOLUTION,
];

/**
 * Get a placeholder image based on scene index
 */
export function getPlaceholderImage(sceneIndex: number): string {
  return PLACEHOLDER_IMAGES[sceneIndex % PLACEHOLDER_IMAGES.length];
}

/**
 * Get a placeholder image based on prompt content
 */
export function getPlaceholderImageByPrompt(prompt: string): string {
  const index =
    Math.abs(prompt.split("").reduce((a, b) => a + b.charCodeAt(0), 0)) %
    PLACEHOLDER_IMAGES.length;
  return PLACEHOLDER_IMAGES[index];
}
